-- Project : India Lake Water Quality Analytics (CPCB NWMP 2017-2022)
-- Database: data/lakes.db  (generated by etl/clean_lakes.py)
-- Contents: Q1-Q3b basic counts | Q4-Q5 state & lake rankings
--           Q5b-Q5f coliform outlier checks | Q6 YoY spike detection (LAG)




-- Q1: Number of monitoring stations per state
SELECT state, COUNT(*) AS station_count
FROM dim_station
GROUP BY state
ORDER BY station_count DESC;

-- Query 2: Stations by water body type
SELECT water_body_type, COUNT(*) AS station_count
FROM dim_station
GROUP BY water_body_type
ORDER BY station_count DESC;

-- Query 3: Year-wise station records
SELECT year, COUNT(DISTINCT stn_code) AS station_count
FROM fact_lake_quality
WHERE year BETWEEN 2017 AND 2022
GROUP BY year
ORDER by year;

-- Query 3b: Stations grouped by number of years monitored

SELECT years_monitored, COUNT(*) AS station_count
FROM dim_station
WHERE years_monitored BETWEEN 1 AND 6
GROUP BY years_monitored
ORDER BY years_monitored;

--Query 4 State-wise average of max BOD 
SELECT d.state, 
	ROUND(AVG(f.bod_mg_l_max), 2) AS avg_max_bod, 
	COUNT(*) AS records
FROM fact_lake_quality f
JOIN dim_station d ON f.stn_code = d.stn_code
WHERE f.bod_mg_l_max IS NOT NULL
GROUP BY d.state
HAVING COUNT(*) >= 10
ORDER BY avg_max_bod DESC;

-- Query 5: Top 10 lakes by maximum fecal coliform

SELECT d.station_name, d.state, d.water_body_type,
       MAX(f.fecal_coliform_mpn_max) AS max_fecal_coliform
FROM fact_lake_quality f
JOIN dim_station d
    ON f.stn_code = d.stn_code
WHERE f.fecal_coliform_mpn_max IS NOT NULL
GROUP BY
    d.stn_code,
    d.station_name,
    d.state,
    d.water_body_type
ORDER BY max_fecal_coliform DESC
LIMIT 10;

-- Q5b: Sanity check on the top station across years
SELECT year,
       fecal_coliform_mpn_min,
       fecal_coliform_mpn_max,
       total_coliform_mpn_max
FROM fact_lake_quality
WHERE stn_code = (SELECT stn_code FROM dim_station
                  WHERE station_name LIKE 'HOSAKEREHALLI%')
ORDER BY year;

-- Q5c: Annual count of records with fecal coliform above 10 crore
SELECT f.year,
    COUNT(*) AS high_fecal_coliform_records
FROM fact_lake_quality f
WHERE f.fecal_coliform_mpn_max > 100000000
  AND f.year BETWEEN 2017 AND 2022
GROUP BY f.year
ORDER BY f.year;


-- Q5d:
SELECT d.station_name, d.state, f.year,
       f.fecal_coliform_mpn_min,
       f.fecal_coliform_mpn_max,
       f.total_coliform_mpn_max
FROM fact_lake_quality f
JOIN dim_station d ON f.stn_code = d.stn_code
WHERE f.fecal_coliform_mpn_max > 100000000
ORDER BY f.fecal_coliform_mpn_max DESC;


-- Q5e: Top 10 most frequently repeated total coliform values
SELECT
    total_coliform_mpn_max,
    COUNT(*) AS times_repeated
FROM fact_lake_quality
WHERE total_coliform_mpn_max IS NOT NULL
GROUP BY total_coliform_mpn_max
HAVING COUNT(*) >= 2
ORDER BY total_coliform_mpn_max DESC
LIMIT 10;

-- Q5f: Most frequently repeated total coliform values overall
SELECT total_coliform_mpn_max,
       COUNT(*) AS times_repeated
FROM fact_lake_quality
WHERE total_coliform_mpn_max IS NOT NULL
GROUP BY total_coliform_mpn_max
ORDER BY times_repeated DESC
LIMIT 10;

-- Query 6: Detect year-over-year spikes greater than 100x

WITH yearly AS (
    SELECT
        stn_code,
        year,
        fecal_coliform_mpn_max,
        LAG(fecal_coliform_mpn_max) OVER (
            PARTITION BY stn_code
            ORDER BY year
        ) AS prev_year_value
    FROM fact_lake_quality
    WHERE fecal_coliform_mpn_max IS NOT NULL
)
SELECT
    stn_code,
    year,
    prev_year_value,
    fecal_coliform_mpn_max AS current_year_value,
    ROUND(
        1.0 * fecal_coliform_mpn_max / prev_year_value,
        2
    ) AS spike_ratio
FROM yearly
WHERE prev_year_value > 0
  AND fecal_coliform_mpn_max > prev_year_value * 100
ORDER BY spike_ratio DESC;

-- Query 6: Detect potential fecal coliform spikes
-- Threshold: >100x, with previous value >= 1000
-- Minimum baseline reduces misleading ratios from tiny denominators.

WITH yearly AS (
    SELECT
        stn_code,
        year,
        fecal_coliform_mpn_max,
        LAG(year) OVER (
            PARTITION BY stn_code
            ORDER BY year
        ) AS prev_year,
        LAG(fecal_coliform_mpn_max) OVER (
            PARTITION BY stn_code
            ORDER BY year
        ) AS prev_year_value
    FROM fact_lake_quality
    WHERE fecal_coliform_mpn_max IS NOT NULL
)
SELECT
    d.station_name,
    d.state,
    y.stn_code,
    y.prev_year,
    y.year,
    y.year - y.prev_year AS gap_years,
    y.prev_year_value,
    y.fecal_coliform_mpn_max AS current_year_value,
    ROUND(
        1.0 * y.fecal_coliform_mpn_max / y.prev_year_value,
        2
    ) AS spike_ratio
FROM yearly y
JOIN dim_station d
    ON y.stn_code = d.stn_code
WHERE y.prev_year_value >= 1000
  AND y.fecal_coliform_mpn_max > y.prev_year_value * 100
ORDER BY spike_ratio DESC;

-- Query 7a: DO/BOD-based water quality screening per station-year
-- Source: CPCB, Designated Best Use Water Quality Criteria
-- https://cpcb.nic.in/wqm/Designated_Best_Use_Water_Quality_Criteria.pdf
-- Thresholds checked on: 2026-10-12
-- Note: Screening based only on DO and BOD, not full CPCB classification.

SELECT
    stn_code,
    year,
    do_mg_l_min,
    bod_mg_l_max,
    CASE
        WHEN do_mg_l_min IS NULL
          OR bod_mg_l_max IS NULL
            THEN 'Insufficient data'

        WHEN do_mg_l_min >= 6
         AND bod_mg_l_max <= 2
            THEN 'A'

        WHEN do_mg_l_min >= 5
         AND bod_mg_l_max <= 3
            THEN 'B'

        WHEN do_mg_l_min >= 4
         AND bod_mg_l_max <= 3
            THEN 'C'

        ELSE 'Below C'
    END AS wq_class
FROM fact_lake_quality;

-- Q7b: Share of each DO/BOD class per year (%)

WITH classified AS (
    SELECT
        stn_code,
        year,
        do_mg_l_min,
        bod_mg_l_max,
        CASE
            WHEN do_mg_l_min IS NULL
              OR bod_mg_l_max IS NULL
                THEN 'Insufficient data'

            WHEN do_mg_l_min >= 6
             AND bod_mg_l_max <= 2
                THEN 'A'

            WHEN do_mg_l_min >= 5
             AND bod_mg_l_max <= 3
                THEN 'B'

            WHEN do_mg_l_min >= 4
             AND bod_mg_l_max <= 3
                THEN 'C'

            ELSE 'Below C'
        END AS do_bod_class
    FROM fact_lake_quality
)
SELECT
    year,
    do_bod_class,
    COUNT(*) AS stations,
    ROUND(
        100.0 * COUNT(*)
        / SUM(COUNT(*)) OVER (PARTITION BY year),
        1
    ) AS pct
FROM classified
GROUP BY year, do_bod_class
ORDER BY year, do_bod_class;

-- Q7c: Year-wise DO/BOD class percentage
-- Only stations monitored for all 6 years (2017-2022)

WITH classified AS (
    SELECT
        stn_code,
        year,
        do_mg_l_min,
        bod_mg_l_max,
        CASE
            WHEN do_mg_l_min IS NULL
              OR bod_mg_l_max IS NULL
                THEN 'Insufficient data'

            WHEN do_mg_l_min >= 6
             AND bod_mg_l_max <= 2
                THEN 'A'

            WHEN do_mg_l_min >= 5
             AND bod_mg_l_max <= 3
                THEN 'B'

            WHEN do_mg_l_min >= 4
             AND bod_mg_l_max <= 3
                THEN 'C'

            ELSE 'Below C'
        END AS do_bod_class
    FROM fact_lake_quality
    WHERE stn_code IN (
        SELECT stn_code
        FROM dim_station
        WHERE years_monitored = 6
    )
)
SELECT
    year,
    do_bod_class,
    COUNT(*) AS stations,
    ROUND(
        100.0 * COUNT(*)
        / SUM(COUNT(*)) OVER (PARTITION BY year),
        1
    ) AS pct
FROM classified
GROUP BY year, do_bod_class
ORDER BY year, do_bod_class;

-- Query 7d-1: Compare non-A-C share in 2022
-- Panel groups: 6-year stations vs stations monitored for <6 years

WITH classified AS (
    SELECT
        f.stn_code,
        f.year,
        CASE
            WHEN d.years_monitored = 6 THEN '6-year stations'
            WHEN d.years_monitored < 6 THEN 'Under-6-year stations'
        END AS panel_group,
        CASE
            WHEN f.do_mg_l_min IS NULL
              OR f.bod_mg_l_max IS NULL
                THEN 'Insufficient data'
            WHEN f.do_mg_l_min >= 6
             AND f.bod_mg_l_max <= 2
                THEN 'A'
            WHEN f.do_mg_l_min >= 5
             AND f.bod_mg_l_max <= 3
                THEN 'B'
            WHEN f.do_mg_l_min >= 4
             AND f.bod_mg_l_max <= 3
                THEN 'C'
            ELSE 'Below C'
        END AS do_bod_class
    FROM fact_lake_quality f
    JOIN dim_station d
        ON f.stn_code = d.stn_code
    WHERE f.year = 2022
      AND d.years_monitored IS NOT NULL
      AND d.years_monitored <= 6
)
SELECT
    panel_group,
    COUNT(*) AS total_records,
    SUM(
        CASE
            WHEN do_bod_class = 'Below C' THEN 1
            ELSE 0
        END
    ) AS non_ac_records,
    ROUND(
        100.0 * SUM(
            CASE
                WHEN do_bod_class = 'Below C' THEN 1
                ELSE 0
            END
        ) / COUNT(*),
        1
    ) AS non_ac_pct
FROM classified
WHERE panel_group IS NOT NULL
  AND do_bod_class <> 'Insufficient data'
GROUP BY panel_group
ORDER BY non_ac_pct DESC;

-- Query 7d-2: State-wise count of stations monitored for all 6 years

SELECT
    state,
    COUNT(DISTINCT stn_code) AS station_count
FROM dim_station
WHERE years_monitored = 6
GROUP BY state
ORDER BY station_count DESC, state
LIMIT 3;

-- Q7e: stations added after 2017, by state
SELECT state,
       COUNT(*) AS total_stations,
       SUM(CASE WHEN first_year > 2017 THEN 1 ELSE 0 END) AS added_after_2017
FROM dim_station
GROUP BY state
ORDER BY added_after_2017 DESC
LIMIT 5;